import { useState } from 'react';
import { useQuery, keepPreviousData } from '@tanstack/react-query';

interface UsersPage {
  users: User[];
  nextPage: number | null;
  totalPages: number;
}

async function fetchUsersPage(page: number): Promise<UsersPage> {
  const res = await fetch(`/api/users?page=${page}`);
  return res.json();
}

function UserList() {
  const [page, setPage] = useState(1);

  const {
    data,
    isLoading,
    isPlaceholderData,
    isFetching,
  } = useQuery({
    queryKey: ['users', 'list', page],
    queryFn: () => fetchUsersPage(page),
    placeholderData: keepPreviousData,
    staleTime: 1000 * 60 * 2,
  });

  return (
    <div>
      {isLoading && <p className="loading">Loading page {page}...</p>}

      <ul className="user-list">
        {data?.users.map((user) => (
          <li key={user.id}>
            <strong>{user.name}</strong> â€” {user.email}
          </li>
        ))}
      </ul>

      <nav className="pagination">
        <button
          onClick={() => setPage((p) => Math.max(1, p - 1))}
          disabled={page === 1 || isLoading}
        >
          Previous
        </button>

        <span className="page-indicator">
          Page {page} of {data?.totalPages ?? '?'}
          {isFetching && !isPlaceholderData && <em> (fetching...)</em>}
        </span>

        <button
          onClick={() => setPage((p) => p + 1)}
          disabled={!data?.nextPage || isPlaceholderData}
        >
          {isPlaceholderData ? 'Loading...' : 'Next'}
        </button>
      </nav>
    </div>
  );
}

